input.new_string:
export function nextGeneration(livingCells: Cell[]): Cell[] {
  const isLiving = new Set(livingCells.map(String));

  const countLivingNeighbors = ([x, y]: Cell): number => {
    const offsets = [-1, 0, 1];
    return offsets
      .flatMap((dx) => offsets.map((dy) => [dx, dy]))
      .filter(([dx, dy]) => dx !== 0 || dy !== 0)
      .filter(([dx, dy]) => isLiving.has(String([x + dx, y + dy])))
      .length;
  };

  return livingCells.filter((cell) => {
    const neighbors = countLivingNeighbors(cell);
    return neighbors === 2 || neighbors === 3;
  });
}

