  it("brings a dead cell with exactly 3 neighbors to life (reproduction) — '##.'/'#..'/'...' -> (1,1) alive", () => {
    const gen0: Cell[] = [[0, 0], [1, 0], [0, 1]];

    expect(asCellSet(nextGeneration(gen0))).toEqual(
      asCellSet([[0, 0], [1, 0], [0, 1], [1, 1]]),
